244	     * Handles {@link DuplicateHouseholdException} raised on create when another owner already has the
245	     * same last name and address (compared case-insensitively with collapsed whitespace) and the
246	     * request did not opt in via {@code sharesHousehold}. Returns a 409 Conflict whose body carries an
247	     * {@code errors} array naming the {@code lastName} and {@code address} fields.
248	     *
249	     * @param e The {@link DuplicateHouseholdException} to be handled
250	     * @param request {@link HttpServletRequest} object referring to the current request.
251	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
252	     */
253	    @ExceptionHandler(DuplicateHouseholdException.class)
254	    @ResponseBody
255	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
256	        HttpStatus status = HttpStatus.CONFLICT;
257	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
258	        detail.setProperty("errors", List.of("lastName", "address"));
259	        return ResponseEntity.status(status).body(detail);
