49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
71	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
72	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    public OwnerRestControllerV1(ClinicService clinicService,
86	                                 OwnerMapper ownerMapper,
87	                                 PetMapper petMapper,
88	                                 VisitMapper visitMapper) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    /**
111	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
112	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
113	     */
114	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
115	        List<String> missing = new ArrayList<>();
116	        if (isBlank(ownerFieldsDto.getFirstName())) {
117	            missing.add("firstName");
118	        }
119	        if (isBlank(ownerFieldsDto.getLastName())) {
120	            missing.add("lastName");
121	        }
122	        if (isBlank(ownerFieldsDto.getAddress())) {
123	            missing.add("address");
124	        }
125	        if (isBlank(ownerFieldsDto.getCity())) {
126	            missing.add("city");
127	        }
128	        if (isBlank(ownerFieldsDto.getTelephone())) {
129	            missing.add("telephone");
130	        }
131	        if (!missing.isEmpty()) {
132	            throw new RequiredFieldsMissingException(missing);
133	        }
134	    }
135	
136	    private static boolean isBlank(String value) {
137	        return value == null || value.isBlank();
138	    }
139	
140	    /**
141	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
142	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
143	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
144	     * normalized value is what gets stored, returned and used for every address comparison; a value
145	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
146	     * rejects it.
147	     *
148	     * @param address the raw address as supplied by the caller, may be {@code null}
149	     * @return the normalized address ({@code ""} when blank or {@code null})
150	     */
151	    private static String normalizeAddress(String address) {
152	        if (address == null) {
153	            return "";
154	        }
155	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
156	        if (collapsed.isEmpty()) {
157	            return "";
158	        }
159	        String[] tokens = collapsed.split(" ");
160	        StringBuilder sb = new StringBuilder(collapsed.length());
161	        for (int i = 0; i < tokens.length; i++) {
162	            String token = tokens[i];
163	            switch (token) {
164	                case "ST" -> token = "STREET";
165	                case "RD" -> token = "ROAD";
166	                case "AVE" -> token = "AVENUE";
167	                default -> { }
168	            }
169	            if (i > 0) {
170	                sb.append(' ');
171	            }
172	            sb.append(token);
173	        }
174	        return sb.toString();
175	    }
176	
177	    /**
178	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
179	     * A leading {@code +} and its country code are kept as given; otherwise the country code
180	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
181	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
182	     * stored and returned.
183	     *
184	     * @param telephone the raw telephone as supplied by the caller
185	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
186	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
187	     */
188	    private static String normalizeTelephone(String telephone) {
189	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
190	        String e164;
191	        if (cleaned.startsWith("+")) {
192	            e164 = "+" + cleaned.substring(1);
193	        } else {
194	            String national = cleaned;
195	            if (national.startsWith("0")) {
196	                national = national.substring(1);
197	            }
198	            e164 = "+61" + national;
199	        }
200	        String digits = e164.substring(1);
201	        if (!digits.matches("\\d{8,15}")) {
202	            throw new InvalidTelephoneException(
203	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
204	        }
205	        return e164;
206	    }
207	
208	    /**
209	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
210	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
211	     *
212	     * @param email the raw email as supplied by the caller, may be {@code null}
213	     * @return the lower-cased email, or {@code null} when none was supplied
214	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
215	     */
216	    private static String normalizeEmail(String email) {
217	        if (email == null || email.isBlank()) {
218	            return null;
219	        }
220	        String trimmed = email.trim();
221	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
222	            throw new InvalidEmailException("Email must be a syntactically valid address");
223	        }
224	        return trimmed.toLowerCase(Locale.ROOT);
225	    }
226	
227	    /**
228	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
229	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
230	     * direct equality comparison of the E.164 values against the stored values is sufficient.
231	     *
232	     * @param normalizedTelephone the E.164 telephone of the owner being created
233	     * @throws DuplicateTelephoneException if another owner already uses this telephone
234	     */
235	    private void rejectDuplicateTelephone(String normalizedTelephone) {
236	        boolean inUse = this.clinicService.findAllOwners().stream()
237	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
238	        if (inUse) {
239	            throw new DuplicateTelephoneException(
240	                "Telephone is already used by another owner");
241	        }
242	    }
243	
244	    /**
245	     * Rejects a create that would place the owner in a household already occupied by another owner,
246	     * i.e. one whose last name and address match the supplied values. The two fields are compared
247	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
248	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
249	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
250	     * by setting {@code sharesHousehold} to {@code true}.
251	     *
252	     * @param lastName the last name of the owner being created
253	     * @param address the address of the owner being created
254	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
255	     */
256	    private void rejectDuplicateHousehold(String lastName, String address) {
257	        String normalizedLastName = normalizeForHousehold(lastName);
258	        String normalizedAddress = normalizeForHousehold(address);
259	        boolean inHousehold = this.clinicService.findAllOwners().stream()
260	            .anyMatch(existing ->
261	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
262	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
263	        if (inHousehold) {
264	            throw new DuplicateHouseholdException(
265	                "An owner with the same last name and address already exists");
266	        }
267	    }
268	
269	    /**
270	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
271	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
272	     *
273	     * @param value the raw value, may be {@code null}
274	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
275	     */
276	    private static String normalizeForHousehold(String value) {
277	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
278	    }
279	
280	    /**
281	     * Derives the stable household identifier for an owner from the normalized last name and address.
282	     * The value is a deterministic function of those two fields (compared case-insensitively with
283	     * collapsed whitespace, exactly as {@link #rejectDuplicateHousehold}), so every owner in the same
284	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
285	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
286	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
287	     * normalized fields.
288	     *
289	     * @param lastName the last name of the owner being created
290	     * @param address the address of the owner being created
291	     * @return the stable household identifier
292	     */
293	    private static String householdId(String lastName, String address) {
294	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
295	        try {
296	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
297	            StringBuilder sb = new StringBuilder(digest.length * 2);
298	            for (byte b : digest) {
299	                sb.append(String.format("%02x", b));
300	            }
301	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
302	        } catch (NoSuchAlgorithmException e) {
303	            throw new IllegalStateException("SHA-256 not available", e);
304	        }
305	    }
306	
307	    /**
308	     * The maximum number of owners a single city may contain. A create whose city already holds this
309	     * many owners is rejected, so a city never grows beyond this capacity.
310	     */
311	    private static final int CITY_CAPACITY = 50;
312	
313	    /**
314	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
315	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
316	     * trimmed, exactly as {@link #nextCustomerCode} counts a city's owners. The count reflects the
317	     * state before the new owner is persisted, so it excludes the owner being created.
318	     *
319	     * @param city the city of the owner being created
320	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
321	     */
322	    private void rejectCityAtCapacity(String city) {
323	        String normalizedCity = normalizeName(city);
324	        long ownersInCity = this.clinicService.findAllOwners().stream()
325	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
326	            .count();
327	        if (ownersInCity >= CITY_CAPACITY) {
328	            throw new CityAtCapacityException(
329	                "The city already contains the maximum number of owners");
330	        }
331	    }
332	
333	    /**
334	     * Builds the customer code assigned to an owner on create, formatted
335	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters
336	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
337	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
338	     * current number of owners already in that city, e.g. {@code 'MEL-SMI-0007'}.
339	     *
340	     * @param city the city of the owner being created
341	     * @param lastName the last name of the owner being created
342	     * @return the formatted customer code
343	     */
344	    private String nextCustomerCode(String city, String lastName) {
345	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
346	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
347	        String normalizedCity = normalizeName(city);
348	        int sequence = (int) this.clinicService.findAllOwners().stream()
349	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
350	            .count() + 1;
351	        return String.format("%s-%s-%04d", city3, last3, sequence);
352	    }
353	
354	    /**
355	     * Counts the existing owners that share the owner-to-be's first and last name, compared
356	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
357	     * new owner is persisted, so it excludes the owner being created.
358	     *
359	     * @param firstName the first name of the owner being created
360	     * @param lastName the last name of the owner being created
361	     * @return the number of existing owners with the same first and last name
362	     */
363	    private int countNamesakes(String firstName, String lastName) {
364	        String normalizedFirstName = normalizeName(firstName);
365	        String normalizedLastName = normalizeName(lastName);
366	        return (int) this.clinicService.findAllOwners().stream()
367	            .filter(existing ->
368	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
369	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
370	            .count();
371	    }
372	
373	    /**
374	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
375	     * lower-casing.
376	     *
377	     * @param value the raw name, may be {@code null}
378	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
379	     */
380	    private static String normalizeName(String value) {
381	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
382	    }
383	
384	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
385	    @Override
386	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
387	        Owner owner = this.clinicService.findOwnerById(ownerId);
388	        if (owner == null) {
389	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
390	        }
391	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
392	    }
393	
394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Override
396	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
397	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
398	        validateRequiredFields(ownerFieldsDto);
399	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
400	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
401	        }
402	        rejectCityAtCapacity(ownerFieldsDto.getCity());
403	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
404	        rejectDuplicateTelephone(normalizedTelephone);
405	        ownerFieldsDto.setTelephone(normalizedTelephone);
406	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
407	        if (ownerFieldsDto.getRegistrationDate() == null) {
408	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
409	        }
410	        HttpHeaders headers = new HttpHeaders();
411	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
412	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
413	        owner.setHouseholdId(householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()));
414	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
415	        this.clinicService.saveOwner(owner);
416	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
417	        headers.setLocation(UriComponentsBuilder.newInstance()
418	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
419	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
420	    }
421	
422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
425	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
426	        if (currentOwner == null) {
427	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
428	        }
429	        currentOwner.setAddress(ownerFieldsDto.getAddress());
430	        currentOwner.setCity(ownerFieldsDto.getCity());
431	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
432	        currentOwner.setLastName(ownerFieldsDto.getLastName());
433	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
434	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
435	        this.clinicService.saveOwner(currentOwner);
436	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
437	    }
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Transactional
441	    @Override
442	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
443	        Owner owner = this.clinicService.findOwnerById(ownerId);
444	        if (owner == null) {
